import { readFileSync, writeFileSync } from 'node:fs'
import { JSDOM, VirtualConsole, ResourceLoader } from 'jsdom'

const WORKSPACE = '/tmp/disco-sbx-zq4jvgdz/sbx_594605d1f07c4ec4a9647cb28cc53a21'
const DIST = `${WORKSPACE}/dist`

const html = readFileSync(`${DIST}/index.html`, 'utf8')
// Rewrite every asset path to absolute file:// so jsdom can load them
// locally instead of trying to fetch from http://localhost/.
const fixedHtml = html
  .replace(/(href|src)="\//g, `$1="file://${DIST}/`)
  .replace(/(href|src)="\.\//g, `$1="file://${DIST}/`)

writeFileSync('/tmp/react-render-check/fixed.html', fixedHtml)

// Block all external network requests (Google Fonts, etc.) — we only
// care about the React render, not typography.
class NoNetLoader extends ResourceLoader {
  fetch(url, options) {
    if (url.startsWith('file://')) return super.fetch(url, options)
    return Promise.resolve(Buffer.from(''))
  }
}

const virtualConsole = new VirtualConsole()
const consoleErrors = []
virtualConsole.on('jsdomError', (err) => consoleErrors.push(String(err)))
virtualConsole.on('error', (err) => consoleErrors.push(String(err)))

const dom = new JSDOM(fixedHtml, {
  url: `file://${DIST}/index.html`,
  runScripts: 'dangerously',
  resources: new NoNetLoader(),
  pretendToBeVisual: true,
  virtualConsole,
})

await new Promise((r) => setTimeout(r, 600))

