// SSR render check — actually executes src/App.jsx and asserts
// the heading "React Restart 91304" is in the rendered HTML.
import { createServer } from 'vite'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const projectRoot = '/workspace'
const here = path.dirname(fileURLToPath(import.meta.url))

const server = await createServer({
  root: projectRoot,
  appType: 'custom',
  server: { middlewareMode: true, hmr: false },
  logLevel: 'error',
})

try {
  // Load the App component as a Vite SSR module (this executes the JSX).
  const mod = await server.ssrLoadModule('/src/App.jsx')
  const App = mod.default
  if (typeof App !== 'function') {
    console.log(JSON.stringify({ result: 'FAIL', reason: 'App default export is not a function', gotType: typeof App }))
    process.exit(1)
  }

  // Use the same React + ReactDOMServer versions the project resolved.
  const reactMod = await server.ssrLoadModule('react')
  const React = reactMod.default || reactMod
  const rdsMod = await server.ssrLoadModule('react-dom/server')
  const renderToString = rdsMod.renderToString

  // Vite's SSRLoadModule returns the default export, but for react-dom/server
  // the named export is what we need — fall back to require if necessary.
  const html = (typeof renderToString === 'function')
    ? renderToString(React.createElement(App))
    : renderToString.default(React.createElement(App))

  const hasHeading = /React Restart 91304/.test(html)
  const hasH1 = /<h1[^>]*id="page-heading"[^>]*>React Restart 91304<\/h1>/.test(html)
  const len = html.length
  const snippet = html.slice(0, 400)

  console.log(JSON.stringify({
    result: hasH1 ? 'PASS' : (hasHeading ? 'WEAK' : 'FAIL'),
    renderedLength: len,
    containsHeadingText: hasHeading,
    containsFullH1Element: hasH1,
    renderedHtmlSnippet: snippet,
  }, null, 2))
  process.exit(hasH1 ? 0 : 1)
} catch (err) {
  console.log(JSON.stringify({ result: 'ERROR', error: String(err && err.stack || err) }, null, 2))
  process.exit(2)
} finally {
  await server.close()
}
